# Key binding: key = primary | secondary
# Example: numpad_1 = activate_auto_core | close_program
# Leave a binding blank to return control to the OS

[keymap: concise]
numpad_0 = activate_function_key | deactivate_function_key
numpad_1 = activate_auto_core | close_program
numpad_2 = activate_word | save_file_and_create_new_file
numpad_3 = print_Jace_choice | make_print_choice("Jace", true)
numpad_4 = print_Daniel_choice | activate_chrome
numpad_5 = activate_itunes | activate_spotify
numpad_6 = itunes_next_song | spotify_next_song
numpad_7 = select_and_insert_session_prompt | activate_folder
numpad_8 = start_reddit_new_tab | activate_firefox
numpad_9 = print_timestamp | print_date_iso_with_timestamp_w
numpad_multiply = print_Star_choice | print_episode_title
numpad_add = itunes_print_songs | spotify_print_songs
numpad_decimal = print_Lily_choice | print_James_choice
numpad_enter = print_next_up_song_list | print_next_up_song_list
numpad_subtract = itunes_stop_song | launch_dash
numpad_divide = print_Tyler_choice | report_and_empty_recycle_bin
media_play_pause = itunes_play_pause | print_Eric_choice
browser_home = create_new_note_in_notepad | activate_discord
launch_mail = print_Luna_choice | print_Katrina_choice
launch_calculator = create_new_note_in_notepad | launch_task_list
